CREATE TABLE IF NOT EXISTS `places` (`id` TEXT NOT NULL, `circleId` TEXT NOT NULL, `name` TEXT NOT NULL, `notes` TEXT, `address` TEXT, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `radius` INTEGER NOT NULL, `icon` TEXT, `color` TEXT, `placeType` TEXT NOT NULL, `boundaryRadius` INTEGER, `alertsEnabled` INTEGER NOT NULL DEFAULT 0, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, `sharedCircles` TEXT, `placeKey` TEXT, `wrapViaCircle` TEXT, `ownerUserId` TEXT, `isOwner` INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_places_circleId` ON `places` (`circleId`)
CREATE TABLE IF NOT EXISTS `place_alerts` (`id` TEXT NOT NULL, `placeId` TEXT NOT NULL, `circleId` TEXT, `userId` TEXT NOT NULL, `targetUserId` TEXT NOT NULL, `alertOnArrival` INTEGER NOT NULL, `alertOnDeparture` INTEGER NOT NULL, `activeDays` TEXT, `activeStartTime` TEXT, `activeEndTime` TEXT, `isOvernight` INTEGER NOT NULL, `notifyPush` INTEGER NOT NULL, `notifyEmail` INTEGER NOT NULL, `notifySms` INTEGER NOT NULL, `isRecurring` INTEGER NOT NULL, `isActive` INTEGER NOT NULL, `expiresAt` INTEGER, `dayBucket` INTEGER NOT NULL, `suppressedByTarget` INTEGER, PRIMARY KEY(`id`), FOREIGN KEY(`placeId`) REFERENCES `places`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_place_alerts_placeId` ON `place_alerts` (`placeId`)
CREATE INDEX IF NOT EXISTS `index_place_alerts_targetUserId` ON `place_alerts` (`targetUserId`)
CREATE INDEX IF NOT EXISTS `index_place_alerts_isActive` ON `place_alerts` (`isActive`)
CREATE TABLE IF NOT EXISTS `locations` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `circleId` TEXT NOT NULL, `userId` TEXT NOT NULL, `deviceId` TEXT NOT NULL, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `altitude` REAL, `speed` REAL, `heading` REAL, `accuracy` REAL, `batteryLevel` INTEGER, `timestamp` INTEGER NOT NULL, `isSynced` INTEGER NOT NULL, `dayBucket` INTEGER NOT NULL, `allowAlertsOnMe` INTEGER)
CREATE INDEX IF NOT EXISTS `index_locations_circleId` ON `locations` (`circleId`)
CREATE INDEX IF NOT EXISTS `index_locations_userId` ON `locations` (`userId`)
