CREATE TABLE IF NOT EXISTS `sos_alerts` (`id` TEXT NOT NULL, `circleId` TEXT NOT NULL, `userId` TEXT NOT NULL, `status` TEXT NOT NULL, `latitude` REAL, `longitude` REAL, `acknowledgedBy` TEXT, `createdAt` INTEGER NOT NULL, `resolvedAt` INTEGER, `acknowledgedByMe` INTEGER NOT NULL, `dismissedByMe` INTEGER NOT NULL, `dismissedAt` INTEGER, `acknowledgmentCount` INTEGER NOT NULL, PRIMARY KEY(`id`))
